// FoundationStereo's EdgeNeXt-small backbone (timm `edgenext_small`, `Feature.stem` /
// `Feature.stages`), piece by piece, against timm in FP64.
//
// Full stage widths on small maps, with seeded random weights (LayerNorm affines and
// layer scales randomised too). Fixtures generated by tests/fixtures/edgenext/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::feature::edgenext::{
    DIMS, KERNELS, SPLITS, backbone, conv_block, downsample, split_transpose_block, stem,
};

/// `stem` then `stages[0]` (identity downsample, 3 ConvBlocks with k 3) on a 32x48 image.
#[test]
#[serial]
fn stem_and_stage0_match_timm() -> anyhow::Result<()> {
    check_block(
        "edgenext/stem_stage0",
        "edgenext/stem_stage0",
        &[("x", &[1, 3, 32, 48])],
        |i| {
            let mut x = stem::<f32>(&i[0]);
            let _s = name_scope("stages");
            let _0 = name_scope("0");
            let _b = name_scope("blocks");
            for b in 0..3 {
                let _g = name_scope(b.to_string());
                x = conv_block::<f32>(&x, DIMS[0], KERNELS[0]);
            }
            vec![("", x)]
        },
        1e-4,
    )?;
    Ok(())
}

/// `stages[1].downsample` (LayerNorm2d, 2x2 stride-2 conv to 96) and its two
/// ConvBlocks (k 5), on an 8x12 map.
#[test]
#[serial]
fn stage1_downsample_and_conv_blocks_match_timm() -> anyhow::Result<()> {
    check_block(
        "edgenext/stage1_convs",
        "edgenext/stage1_convs",
        &[("x", &[1, DIMS[0], 8, 12])],
        |i| {
            let _s = name_scope("stages");
            let _1 = name_scope("1");
            let mut x = downsample::<f32>(&i[0], DIMS[0], DIMS[1]);
            let _b = name_scope("blocks");
            for b in 0..2 {
                let _g = name_scope(b.to_string());
                x = conv_block::<f32>(&x, DIMS[1], KERNELS[1]);
            }
            vec![("", x)]
        },
        1e-4,
    )?;
    Ok(())
}

/// Stage `i`'s `SplitTransposeBlock` (the last block in `stages[i]`).
fn check_stb(i: usize, idx: usize, hw: [usize; 2]) -> anyhow::Result<()> {
    let dir = format!("edgenext/stb_stage{i}");
    check_block(
        &dir,
        &dir,
        &[("x", &[1, DIMS[i], hw[0], hw[1]])],
        |x| {
            let _s = name_scope("stages");
            let _i = name_scope(i.to_string());
            let _b = name_scope("blocks");
            let _n = name_scope(idx.to_string());
            vec![(
                "",
                split_transpose_block::<f32>(&x[0], DIMS[i], SPLITS[i], i == 1),
            )]
        },
        1e-4,
    )?;
    Ok(())
}

/// Stage 1's `SplitTransposeBlock`: 96 channels in 2 groups (one depthwise conv),
/// Fourier positional encoding, XCA with 8 heads of 12 channels, on a 6x10 map.
#[test]
#[serial]
fn split_transpose_block_stage1_matches_timm() -> anyhow::Result<()> {
    check_stb(1, 2, [6, 10])
}

/// Stage 2's: 160 channels in 3 uneven groups (54, 54, 52), no positional encoding,
/// heads of 20 channels, on a 5x7 map.
#[test]
#[serial]
fn split_transpose_block_stage2_matches_timm() -> anyhow::Result<()> {
    check_stb(2, 8, [5, 7])
}

/// Stage 3's: 304 channels in 4 groups, heads of 38 channels, on a 3x5 map.
#[test]
#[serial]
fn split_transpose_block_stage3_matches_timm() -> anyhow::Result<()> {
    check_stb(3, 2, [3, 5])
}

/// The whole backbone with a real FoundationStereo checkpoint's `feature.stem` /
/// `feature.stages` weights (all 18 blocks) on the sample left image at 224x320,
/// against timm in FP64. Outputs reach ~300, so the tolerance is absolute 1e-3
/// (~3e-6 relative). Build the fixtures with tests/fixtures/edgenext/gen_real.py,
/// point `FS_REAL_FIXTURES` at the directory holding `edgenext_real/` and run with
/// `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn backbone_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/edgenext_real");
    check_block(
        "edgenext_real",
        &dir,
        &[("x", &[1, 3, 224, 320])],
        |i| {
            let [x4, x8, x16, x32] = backbone::<f32>(&i[0]);
            vec![("x4", x4), ("x8", x8), ("x16", x16), ("x32", x32)]
        },
        1e-3,
    )?;
    Ok(())
}
